def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Find the single non-zero color
    colors = {v for row in grid for v in row if v != 0}
    if not colors:
        return [row[:] for row in grid]
    color = next(iter(colors))

    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    ptset = set(pts)

    # Score translation vectors by how often they map a colored cell to another colored cell.
    vectors = []
    seen = set()
    for r1, c1 in pts:
        for r2, c2 in pts:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 and dc == 0:
                continue
            if (dr, dc) in seen:
                continue
            seen.add((dr, dc))
            score = 0
            for r, c in pts:
                if (r + dr, c + dc) in ptset:
                    score += 1
            if score >= 2:
                vectors.append((score, dr, dc))

    vectors.sort(reverse=True)

    # Keep only a few strong, small vectors.
    chosen = []
    for score, dr, dc in vectors:
        if len(chosen) >= 2:
            break
        if abs(dr) <= h and abs(dc) <= w:
            # avoid near-duplicate directions
            ok = True
            for er, ec in chosen:
                if (dr, dc) == (er, ec) or (dr, dc) == (-er, -ec):
                    ok = False
                    break
            if ok:
                chosen.append((dr, dc))

    # If nothing useful found, just replace background with 5.
    if not chosen:
        return [[v if v != 0 else 5 for v in row] for row in grid]

    out = [[5 for _ in range(w)] for _ in range(h)]

    # Preserve original colored cells
    for r, c in pts:
        out[r][c] = color

    # Closure under the chosen translations
    changed = True
    filled = set(pts)
    while changed:
        changed = False
        current = list(filled)
        for r, c in current:
            for dr, dc in chosen:
                for sgn in (-1, 1):
                    nr, nc = r + sgn * dr, c + sgn * dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in filled:
                        filled.add((nr, nc))
                        out[nr][nc] = color
                        changed = True

    return out

